CREATE OR REPLACE FUNCTION public.admin_save_player_account(p_actor uuid,p_player uuid,p_user uuid,p_name text,p_house text,p_active boolean,p_edit boolean,p_change boolean,p_folder text,p_password_set boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; BEGIN IF NOT public.has_role(p_actor,'admin') THEN RAISE EXCEPTION 'Acesso restrito ao Narrador'; END IF; PERFORM pg_advisory_xact_lock(hashtext(coalesce(p_user::text,p_player::text,p_name))); IF NOT EXISTS(SELECT 1 FROM public.house_catalog WHERE id=p_house) THEN RAISE EXCEPTION 'Casa não cadastrada'; END IF; IF p_player IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.campaign_players WHERE id=p_player) THEN RAISE EXCEPTION 'Jogador não encontrado'; END IF; IF p_player IS NOT NULL THEN pid:=p_player; ELSIF p_user IS NOT NULL THEN SELECT id INTO pid FROM public.campaign_players WHERE user_id=p_user; END IF; IF EXISTS(SELECT 1 FROM public.campaign_players WHERE user_id=p_user AND id IS DISTINCT FROM pid) THEN RAISE EXCEPTION 'Conta já vinculada a outro jogador'; END IF; IF pid IS NULL THEN INSERT INTO public.campaign_players(name,user_id,roster_house_id,active,require_password_change,folder_id) VALUES(p_name,p_user,p_house,p_active,p_change,p_folder) RETURNING id INTO pid; ELSE UPDATE public.campaign_players SET name=p_name,user_id=p_user,roster_house_id=p_house,active=p_active,require_password_change=p_change,folder_id=p_folder WHERE id=pid; END IF; INSERT INTO public.house_memberships(player_id,house_id,can_edit,authorized_by) VALUES(pid,p_house,p_edit,p_actor) ON CONFLICT(player_id,house_id) DO UPDATE SET can_edit=excluded.can_edit,authorized_by=excluded.authorized_by; INSERT INTO public.campaign_admin_audit(actor,target_player,action,details) VALUES(p_actor,pid,CASE WHEN p_password_set THEN 'account_password_set' ELSE 'player_management' END,jsonb_build_object('active',p_active,'requireChange',p_change,'houseId',p_house)); RETURN pid; END $$;
REVOKE ALL ON FUNCTION public.admin_save_player_account(uuid,uuid,uuid,text,text,boolean,boolean,boolean,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admin_save_player_account(uuid,uuid,uuid,text,text,boolean,boolean,boolean,text,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.save_letter_batch_drafts(p_kind text,p_number integer,p_subject text,p_content text,p_recipients text[],p_key uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r text;sent integer:=0;n integer; BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Somente o Narrador prepara missivas'; END IF; IF p_kind NOT IN('geral','reservada') OR cardinality(p_recipients)=0 OR (p_kind='reservada' AND cardinality(p_recipients)<>1) THEN RAISE EXCEPTION 'Destinatários inválidos'; END IF; n:=coalesce(p_number,public.open_letter_round()+1,(SELECT coalesce(max(number),0)+1 FROM public.letter_rounds)); FOREACH r IN ARRAY p_recipients LOOP IF left(r,2)<>'h:' OR NOT EXISTS(SELECT 1 FROM public.campaign_houses WHERE id=substring(r FROM 3)) THEN RAISE EXCEPTION 'Casa inválida'; END IF; INSERT INTO public.campaign_letters(id,sender_user_id,sender_name,recipient_house_id,subject,content,letter_number,letter_kind,batch_key,publication_state) VALUES(gen_random_uuid(),auth.uid(),'Mestre',substring(r FROM 3),p_subject,p_content,n,p_kind,p_key,'draft') ON CONFLICT(batch_key,coalesce(recipient_player_id::text,''),coalesce(recipient_house_id,'')) WHERE batch_key IS NOT NULL DO NOTHING; IF FOUND THEN sent:=sent+1; END IF; END LOOP; RETURN sent; END $$;
REVOKE ALL ON FUNCTION public.save_letter_batch_drafts(text,integer,text,text,text[],uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_letter_batch_drafts(text,integer,text,text,text[],uuid) TO authenticated;